/** One entry of a `group(...)` or `months(...)` read. */
export interface GroupRow {
  key: string;
  /** months(): the month's short name ("May"); group(): the key again. */
  label: string;
  total: number;
  count: number;
  /** Share of the whole, a whole percentage (group() only; 0 for months()). */
  share: number;
  /** A ring's legend line: "Operating · 51%" (group()); the month name (months()). */
  legend: string;
  /** group(): every entry added up, worded like the legend's figures ("AED 1,234.00") — what a ring says in its hole. */
  sum?: string;
}

/** "1234567.50" → "1,234,567.50": the whole part of a toFixed figure grouped in threes, right to left (a loop, not a backtracking regex). */
