/** The first <top> entries, and one more holding all the rest (`top=<n>`). */
function foldEntriesPastTop(out: GroupRow[], top: number, other: string): GroupRow[] {
  const rest = out.slice(top);
  // `other=<one>|<many>` words the folded entry, # being how many it holds
  // ("# other account|# other accounts"); "Other" when it is not given
  const [one = 'Other', many = one] = other.split('|');
  const label = (rest.length === 1 ? one : many).replaceAll('#', String(rest.length));
  return [
    ...out.slice(0, top),
    {
      key: label,
      label,
      total: rest.reduce((s, g) => s + g.total, 0),
      count: rest.reduce((s, g) => s + g.count, 0),
      share: 0,
      legend: label,
    },
  ];
}

/** An entry for the part of a known whole the entries leave unaccounted (`whole=<n>;rest=<label>`). */
function addRestOfWhole(out: GroupRow[], whole: number, rest: string): void {
  const held = out.reduce((s, g) => s + g.total, 0);
  if (held < whole - 0.0001) {
    const label = rest || 'Rest';
    out.push({ key: label, label, total: whole - held, count: 0, share: 0, legend: label });
  }
}

/** Each entry's share of the whole, its legend line, and the whole as worded (`unit=` adds the figures). */
function wordEntryShares(out: GroupRow[], unit: string | undefined): void {
  const sum = out.reduce((s, g) => s + Math.max(0, g.total), 0);
  for (const g of out) {
    g.share = sum > 0 ? Math.round((Math.max(0, g.total) / sum) * 100) : 0;
    // `unit=<code>`: the legend carries the figure too ("Operating · AED 1,234.00 · 51%")
    const figure = unit ? ' · ' + unit + ' ' + withThousands(g.total.toFixed(2)) : '';
    g.legend = g.label + figure + ' · ' + g.share + '%';
    g.sum = (unit ? unit + ' ' : '') + withThousands(sum.toFixed(2));
  }
}

/**
 * `group(<rows>;<key>;<amount>[;option]…)` — the rows of a list gathered by
 * one of their fields: one entry per value of <key>, carrying <amount> added
 * up, how many rows it holds and its share of the whole. Largest total first.
 *
 * Options: `top=<n>` keeps n entries and folds the rest into one keyed
 * "Other"; `positive` leaves out rows of zero or less (a ring divides a
 * positive whole); `blank=<label>` gathers rows with no <key> under <label>
 * instead of leaving them out; `else=<path>` gathers by <path> when no row
 * carries <key> at all; `other=<one>|<many>` words the folded entry (# is how
 * many it holds); `<path>=<value>` filters (see filteredRows).
 *
 * The corporate dashboard's balances by currency and its balance ring (v5;
 * the reference's CurrencyBalances and BalanceMixChart).
 */
function groupRows(obj: unknown, args: string[]): GroupRow[] {
  const [rowsPath = '', keyPath = '', amountPath = '', ...options] = args;
  const positive = options.includes('positive');
  const top = Number(options.find((o) => o.startsWith('top='))?.slice(4));
  const blank = options.find((o) => o.startsWith('blank='))?.slice(6);
  const elsePath = options
    .find((o) => o.startsWith('else='))
    ?.slice(5)
    .trim();
  const other = options.find((o) => o.startsWith('other='))?.slice(6) ?? 'Other';
  const whole = Number(options.find((o) => o.startsWith('whole='))?.slice(6));
  const rest = options.find((o) => o.startsWith('rest='))?.slice(5) ?? '';
  const unitOption = options
    .find((o) => o.startsWith('unit='))
    ?.slice(5)
    .trim();
  // `label=<path>`: an entry is CALLED by this field of its first row (gathered by an id, shown by a name)
  const labelPath =
    options
      .find((o) => o.startsWith('label='))
      ?.slice(6)
      .trim() ?? '';
  const kept = filteredRows(obj, rowsPath, amountPath, options);
  // `unit=@<path>`: the unit is read from the rows themselves — the currency of
  // the accounts gathered, which a screen that opens on "the currency held most
  // of" cannot know when it is drawn
  const unit = unitOption?.startsWith('@')
    ? toStr(getPath(kept[0], unitOption.slice(1)))
    : unitOption;
  // `else=<path>`: when NO row carries the key, the rows are gathered by <path>
  // instead — "by purpose where the bank records one, else by account"
  const byPath =
    elsePath && !kept.some((row) => toStr(getPath(row, keyPath)) !== '') ? elsePath : keyPath;
  let out = gatherGroupEntries(kept, amountPath, byPath, positive, blank, labelPath);
  if (Number.isFinite(top) && top > 0 && out.length > top)
    out = foldEntriesPastTop(out, top, other);
  // `whole=<n>;rest=<label>`: the entries are parts of a known whole (shares out
  // of 100), and what the rows do not account for is an entry of its own — a
  // register that records 90% says nothing about the other 10, and a ring that
  // spread the 90 over the full circle would overstate every holder.
  if (Number.isFinite(whole) && whole > 0) addRestOfWhole(out, whole, rest);
  wordEntryShares(out, unit);
  return out;
}

/** How a month in a chart's axis reads: English until the app's language says otherwise (src/gen/i18n, web). */
export const monthLabels = { of: (month: string): string => month };
const MONTH_NAMES = [
  'Jan',
  'Feb',
  'Mar',
  'Apr',
  'May',
  'Jun',
  'Jul',
  'Aug',
  'Sep',
  'Oct',
  'Nov',
  'Dec',
];

/**
 * `months(<rows>;<date>;<amount>;<n>[;option]…)` — <amount> added up per
 * calendar month (UTC) over the last <n> months including this one, oldest
 * first; a month with no rows is a 0, so a chart keeps its axis. Amounts are
 * taken as sizes (a debit stored negative counts as a debit, not a refund).
 * Options are group()'s row filters, e.g. `creditDebitIndicator=CREDIT`, and
 * `split=<path>:<a>,<b>` — one entry per month AND per value of <path>, in
 * that order (May·a, May·b, Jun·a…), which a bar chart with "bars per group"
 * 2 draws as credits beside debits.
 *
 * The corporate dashboard's credits and debits by month (v5; the reference's
 * TransactionsChart).
 */
function monthRows(obj: unknown, args: string[]): GroupRow[] {
  const [rowsPath = '', datePath = '', amountPath = '', n = '6', ...options] = args;
  const count = Math.max(1, Math.min(36, Math.round(Number(n)) || 6));
  const now = new Date();
  const out: GroupRow[] = [];
  for (let i = count - 1; i >= 0; i--) {
    const d = new Date(Date.UTC(now.getUTCFullYear(), now.getUTCMonth() - i, 1));
    const key = d.getUTCFullYear() + '-' + String(d.getUTCMonth() + 1).padStart(2, '0');
    const label = monthLabels.of(
      /* v8 ignore next -- getUTCMonth() is 0..11, always a name */ MONTH_NAMES[d.getUTCMonth()] ??
        key,
    );
    out.push({ key, label, total: 0, count: 0, share: 0, legend: label });
  }
  const split = options.find((o) => o.startsWith('split='))?.slice(6) ?? '';
  const colon = split.indexOf(':');
  const splitPath = colon > 0 ? split.slice(0, colon).trim() : '';
  const splitValues =
    colon > 0
      ? split
          .slice(colon + 1)
          .split(',')
          .map((x) => x.trim())
          .filter(Boolean)
      : [];
  const parts = splitPath && splitValues.length > 0 ? splitValues : [''];
  const cells = out.flatMap((m) => parts.map((part) => ({ ...m, part })));
  const byKey = new Map(cells.map((c) => [c.key + '|' + c.part, c]));
  for (const row of filteredRows(obj, rowsPath, amountPath, options)) {
    const t = Date.parse(toStr(getPath(row, datePath)));
    if (Number.isNaN(t)) continue;
    const d = new Date(t);
    const part = splitPath ? toStr(getPath(row, splitPath)) : '';
    const c = byKey.get(
      d.getUTCFullYear() + '-' + String(d.getUTCMonth() + 1).padStart(2, '0') + '|' + part,
    );
    if (!c) continue;
    c.total += Math.abs(amountNumber(getPath(row, amountPath)));
    c.count += 1;
  }
  return cells.map(({ part: _part, ...c }) => c);
}

/** `~=` against one row: one of the fields named (`name|accountNumber`) holds the text, whatever the case. */
function rowContainsText(row: unknown, path: string, want: string): boolean {
  const needle = want.toLowerCase();
  // a field written `accountNumber#` is compared with its spaces and dashes
  // taken out, on both sides: an account printed "1234 5678" is typed "12345678"
  const bare = needle.replaceAll(/[\s-]/g, '');
  return path.split('|').some((f) => {
    const field = f.trim();
    if (field.endsWith('#')) {
      return (
        bare !== '' &&
        toStr(getPath(row, field.slice(0, -1)))
          .toLowerCase()
          .replaceAll(/[\s-]/g, '')
          .includes(bare)
      );
    }
    return toStr(getPath(row, field)).toLowerCase().includes(needle);
  });
}

/** What an at-least / at-most condition compares with; null when its `days:`/`months:` count is not a number (every row matches). */
function rangeBoundOf(want: string): string | null {
  if (want.startsWith('days:')) {
    const n = Number(want.slice(5));
    if (want.slice(5).trim() === '' || !Number.isFinite(n)) return null;
    return new Date(Date.now() - n * 86400000).toISOString().slice(0, 10);
  }
  // `months:<n>`: the first day of the month n-1 months back — the start of a
  // window of n calendar months including this one (a 6-month chart's first bar)
  if (want.startsWith('months:')) {
    const n = Number(want.slice(7));
    if (want.slice(7).trim() === '' || !Number.isFinite(n)) return null;
    const now = new Date();
    return new Date(
      Date.UTC(now.getUTCFullYear(), now.getUTCMonth() - Math.max(0, Math.round(n) - 1), 1),
    )
      .toISOString()
      .slice(0, 10);
  }
  return want;
}

/** A row's value at least (`>=`) or at most (any other op) the bound: as numbers when both read as one, else as text. */
function meetsRangeBound(have: string, op: string, bound: string): boolean {
  const a = Number(have);
  const b = Number(bound);
  const numeric = !Number.isNaN(a) && !Number.isNaN(b);
  const left = numeric ? a : have.slice(0, bound.length);
  const right = numeric ? b : bound;
  return op === '>=' ? left >= right : left <= right;
}

/** `?~=`: the row's list is left out or empty, or holds any of the words (`|` between them). */
function absentOrHolds(row: unknown, path: string, want: string): boolean {
  const v = getPath(row, path);
  if (v === undefined || v === null || v === '' || (Array.isArray(v) && v.length === 0))
    return true;
  return want.split('|').some((w) => w.trim() !== '' && rowContainsText(row, path, w.trim()));
}

/** One condition of a `rows(…)` read against one row. */
function rowMatches(row: unknown, path: string, op: string, want: string): boolean {
  // `!~=`: holds NONE of it — the rows a text does not reach (a company outside the path a session acts for)
  if (op === '!~=') return !rowContainsText(row, path, want);
  // `?~=`: an absent or empty list, or one that holds any of the words (`|` between them) — a restriction an entry may
  // leave out to mean "no restriction": a payment purpose the bank approved for EXTERNAL_DOMESTIC payments, or for any
  // (the Edge's purpose-policy admits)
  if (op === '?~=') return absentOrHolds(row, path, want);
  if (op === '~=') return rowContainsText(row, path, want);
  const have = toStr(getPath(row, path));
  if (op === '=' || op === '!=') {
    const hit = want.split('|').some((w) => w.trim() === have);
    return op === '=' ? hit : !hit;
  }
  // `now`: this moment, compared as moments — a row whose deadline has not passed (`expiresAt>=now`); a row with
  // no deadline has none to pass
  if (want === 'now') {
    const t = Date.parse(have);
    if (Number.isNaN(t)) return op === '>=';
    return op === '>=' ? t >= Date.now() : t <= Date.now();
  }
  // at least / at most: `days:<n>` is the day n days ago; numbers compare as
  // numbers, anything else as written (an ISO date sorts as a string)
  const bound = rangeBoundOf(want);
  if (bound === null) return true;
  if (have === '') return false;
  return meetsRangeBound(have, op, bound);
}

/** `via=<path field>:<name field>` applied: each row gains the `rootId` and `rootName` of the root its dotted path starts with. */
function addViaRoots(rows: unknown[], via: string): unknown[] {
  const [pathField = '', nameField = 'name'] = via.split(':').map((x) => x.trim());
  const nameOfId = new Map(
    rows.map((r) => [toStr(getPath(r, 'id')), toStr(getPath(r, nameField))]),
  );
  return rows.map((r) => {
    const own = toStr(getPath(r, 'id'));
    const rootId = toStr(getPath(r, pathField)).split('.')[0] || own;
    return r && typeof r === 'object'
      ? {
          ...(r as Record<string, unknown>),
          rootId,
          rootName: nameOfId.get(rootId) ?? toStr(getPath(r, nameField)),
        }
      : r;
  });
}

/** A `join=` table as a lookup: each <key> to the <value> of the first table row that holds it. */
function joinTableLookup(
  table: unknown,
  keyField: string,
  valueField: string,
): Map<string, unknown> {
  const byKey = new Map<string, unknown>();
  for (const t of Array.isArray(table) ? table : []) {
    const k = toStr(getPath(t, keyField));
    if (k !== '' && !byKey.has(k)) byKey.set(k, getPath(t, valueField));
  }
  return byKey;
}

/** `join=<as>:<table>:<key>:<value>:<field>` applied: each row still without <as> gains it from the table. */
function applyJoinCondition(obj: unknown, rows: unknown[], spec: string): unknown[] {
  // read from both ends: the table in the middle may itself be a grouped read holding colons
  const parts = spec.split(':').map((x) => x.trim());
  if (parts.length < 5) return rows;
  /* v8 ignore next -- five parts or more: the first is there */
  const as = parts[0] ?? '';
  const [keyField = 'id', valueField = 'name', rowField = 'id'] = parts.slice(-3);
  const tablePath = parts.slice(1, -3).join(':');
  const byKey = joinTableLookup(getPath(obj, tablePath), keyField, valueField);
  return rows.map((r) => {
    if (!r || typeof r !== 'object' || toStr(getPath(r, as)) !== '') return r;
    const found = byKey.get(toStr(getPath(r, rowField)));
    return found === undefined || toStr(found) === ''
      ? r
      : { ...(r as Record<string, unknown>), [as]: found };
  });
}

/** `cat=<as>:<a>,<b>[:<between>]` applied: each row still without <as> gains the values its fields hold, joined. */
function applyCatCondition(rows: unknown[], spec: string): unknown[] {
  // `cat=<as>:<a>,<b>`: <as>, where still empty, is the values of those fields that hold one, a space
  // between — "a signatory of" + "Modon Holding"; with one field, a fallback ("the name, else the id")
  const c1 = spec.indexOf(':');
  if (c1 <= 0) return rows;
  const as = spec.slice(0, c1).trim();
  // a third part is what goes between them: `cat=caps:c1,c2,c3:·` reads "View · Initiate payments"
  const c2 = spec.indexOf(':', c1 + 1);
  const between = c2 > c1 ? ' ' + spec.slice(c2 + 1).trim() + ' ' : ' ';
  const fields = spec
    .slice(c1 + 1, c2 > c1 ? c2 : undefined)
    .split(',')
    .map((x) => x.trim())
    .filter(Boolean);
  return rows.map((r) => {
    if (!r || typeof r !== 'object' || toStr(getPath(r, as)) !== '') return r;
    const text = fields
      .map((f) => toStr(getPath(r, f)))
      .filter((x) => x !== '')
      .join(between);
    return text === '' ? r : { ...(r as Record<string, unknown>), [as]: text };
  });
}

/** The `<word>=<text>` entries of a `map=` or `has=`, parted by `~`. */
function wordConditionEntries(list: string): Array<[string, string]> {
  const words: Array<[string, string]> = [];
  for (const pair of list.split('~')) {
    const eq = pair.indexOf('=');
    if (eq > 0) words.push([pair.slice(0, eq).trim(), pair.slice(eq + 1).trim()]);
  }
  return words;
}

/** The entry a field's text picks: for `has=` the first entry it holds as a word, for `map=` its whole value, else `*`. */
function pickWordConditionEntry(
  words: Array<[string, string]>,
  value: string,
  holds: boolean,
): [string, string] | undefined {
  const held = holds ? new Set(value.split(/[\s,]+/).filter(Boolean)) : undefined;
  return held
    ? words.find(([k]) => held.has(k))
    : (words.find(([k]) => k === value) ?? words.find(([k]) => k === '*'));
}

/** `map=` / `has=<as>:<field>:<word>=<text>~…` applied: each row still without <as> gains it, worded from <field>. */
function applyWordCondition(rows: unknown[], spec: string, holds: boolean): unknown[] {
  // `map` words the field's whole value; `has` the FIRST entry the field's text holds as one of
  // its words ("corporate:admin corporate:standard" holds corporate:admin) — a list of roles
  // read as the strongest. Entries are parted by `~` (a `|` would end the token a path sits in).
  const c1 = spec.indexOf(':');
  const c2 = spec.indexOf(':', c1 + 1);
  if (c1 <= 0 || c2 <= c1) return rows;
  const as = spec.slice(0, c1).trim();
  const field = spec.slice(c1 + 1, c2).trim();
  const words = wordConditionEntries(spec.slice(c2 + 1));
  return rows.map((r) => {
    if (!r || typeof r !== 'object' || toStr(getPath(r, as)) !== '') return r;
    const hit = pickWordConditionEntry(words, toStr(getPath(r, field)), holds);
    return hit === undefined ? r : { ...(r as Record<string, unknown>), [as]: hit[1] };
  });
}

/** One `join=` / `cat=` / `map=` / `has=` condition applied to the rows; any other condition leaves them as they are. */
function applyDecorationCondition(obj: unknown, rows: unknown[], condition: string): unknown[] {
  if (condition.startsWith('join=')) return applyJoinCondition(obj, rows, condition.slice(5));
  if (condition.startsWith('cat=')) return applyCatCondition(rows, condition.slice(4));
  if (condition.startsWith('map=') || condition.startsWith('has='))
    return applyWordCondition(rows, condition.slice(4), condition.startsWith('has='));
  return rows;
}

/** How a `rows(…)` read orders and cuts the rows it keeps (`top=`, `skip=`, `sort=`, `unique=`, `heads=`, `pick=`); the last one written wins. */
interface RowsReadPlan {
  top: number;
  skip: number;
  sort: string;
  unique: string;
  heads: string;
  pick: string;
}

/** A `top=` / `skip=` / `sort=` / `unique=` / `heads=` / `pick=` condition recorded in the plan; false for any other, which filters. */
function recordRowsReadOption(plan: RowsReadPlan, path: string, op: string, want: string): boolean {
  if (op !== '=') return false;
  switch (path) {
    case 'top':
      plan.top = Math.max(0, Math.round(Number(want)) || 0);
      return true;
    case 'skip':
      plan.skip = Math.max(0, Math.round(Number(want)) || 0);
      return true;
    case 'sort':
      plan.sort = want;
      return true;
    case 'unique':
      plan.unique = want;
      return true;
    case 'heads':
      plan.heads = want;
      return true;
    case 'pick':
      plan.pick = want;
      return true;
    default:
      return false;
  }
}

/** The rows a bare `<path>` condition keeps (those holding a value there), or a `!<path>` one (those holding none). */
function applyPresenceCondition(rows: unknown[], condition: string): unknown[] {
  if (condition.startsWith('!'))
    return rows.filter((row) => toStr(getPath(row, condition.slice(1))) === '');
  if (condition !== '') return rows.filter((row) => toStr(getPath(row, condition)) !== '');
  return rows;
}

/** The rows one comparison keeps; with an empty value a filter keeps them all, and a `==` lookup none. */
function applyComparisonCondition(
  rows: unknown[],
  path: string,
  op: string,
  want: string,
): unknown[] {
  // a LOOKUP: nothing to look for finds nothing (a filter that is not set filters nothing)
  if (op === '==')
    return want === '' ? [] : rows.filter((row) => toStr(getPath(row, path)) === want);
  return want === '' ? rows : rows.filter((row) => rowMatches(row, path, op, want));
}

/** The filters of a `rows(…)` read applied in the order written, and the ordering and cutting its options ask for. */
function applyFilterConditions(
  rows: unknown[],
  conditions: string[],
): { kept: unknown[]; plan: RowsReadPlan } {
  const plan: RowsReadPlan = { top: 0, skip: 0, sort: '', unique: '', heads: '', pick: '' };
  let kept = rows;
  for (const condition of conditions) {
    if (
      condition.startsWith('via=') ||
      condition.startsWith('join=') ||
      condition.startsWith('map=') ||
      condition.startsWith('has=') ||
      condition.startsWith('cat=')
    )
      continue;
    const m = splitComparison(condition, ['?~=', '!~=', '!=', '~=', '>=', '<=', '==', '=']);
    if (!m) {
      // a bare <path>: the rows that HOLD one; `!<path>`: the rows that do not
      kept = applyPresenceCondition(kept, condition);
      continue;
    }
    const path = m.path.trim();
    const want = m.want.trim();
    if (!recordRowsReadOption(plan, path, m.op, want))
      kept = applyComparisonCondition(kept, path, m.op, want);
  }
  return { kept, plan };
}

/** A row's field as `sort=` compares it: a number as it is, anything else as its text. */
function rowSortValue(row: unknown, by: string): string | number {
  const v = getPath(row, by);
  return typeof v === 'number' ? v : toStr(v);
}

/** Two rows in the order a `sort=` puts them: the first key that tells them apart decides. */
function compareRowsBySortKeys(
  p: unknown,
  q: unknown,
  keys: ReadonlyArray<{ by: string; desc: boolean }>,
): number {
  for (const { by, desc } of keys) {
    const a = rowSortValue(p, by);
    const b = rowSortValue(q, by);
    const order =
      typeof a === 'number' && typeof b === 'number' ? a - b : String(a).localeCompare(String(b));
    if (order !== 0) return desc ? -order : order;
  }
  return 0;
}

/** `sort=<a>,<b>:desc` applied: a sorted copy of the rows. */
function sortRowsByKeys(rows: unknown[], sort: string): unknown[] {
  // `sort=<a>,<b>:desc`: by <a>, then by <b> where <a> is equal — numbers as numbers, the rest as text
  const keys = sort
    .split(',')
    .map((k) => k.trim())
    .filter(Boolean)
    .map((k) =>
      k.endsWith(':desc') ? { by: k.slice(0, -5), desc: true } : { by: k, desc: false },
    );
  return [...rows].sort((p, q) => compareRowsBySortKeys(p, q, keys));
}

/** `unique=<a>,<b>` applied: the rows less any that repeat an earlier one in every field named. */
function dropRepeatedRows(rows: unknown[], unique: string): unknown[] {
  const fields = unique
    .split(',')
    .map((x) => x.trim())
    .filter(Boolean);
  const seen = new Set<string>();
  return rows.filter((r) => {
    const key = fields.map((f) => toStr(getPath(r, f))).join(' ');
    if (seen.has(key)) return false;
    seen.add(key);
    return true;
  });
}

/** `heads=<field>` applied: each row marked `firstOf`, true where a run of equal <field> starts. */
function markRunHeads(rows: unknown[], heads: string): unknown[] {
  let last: string | undefined;
  return rows.map((r) => {
    const now = toStr(getPath(r, heads));
    const first = now !== last;
    last = now;
    return r && typeof r === 'object' ? { ...(r as Record<string, unknown>), firstOf: first } : r;
  });
}

/** A `rows(…)` read's plan applied to the rows it kept: sorted, repeats left out, run heads marked, then one page cut. */
function applyRowsReadPlan(rows: unknown[], plan: RowsReadPlan): unknown[] {
  let out = rows;
  if (plan.sort) out = sortRowsByKeys(out, plan.sort);
  // `unique=<a>,<b>`: a row repeating an earlier one in every field named is left out (the same edge
  // read from both of its ends); `heads=<field>`: the first row of each run of equal <field> is marked
  // `firstOf` — a heading above the rows that share it
  if (plan.unique) out = dropRepeatedRows(out, plan.unique);
  if (plan.heads) out = markRunHeads(out, plan.heads);
  // `skip=<n>` then `top=<m>`: one page of a list read whole (skip = page × size)
  if (plan.skip > 0) out = out.slice(plan.skip);
  if (plan.top > 0) out = out.slice(0, plan.top);
  // `pick=<a>,<b>`: each row keeps only those fields — a request that takes rows of another answer
  // (a batch of amounts to convert) is sent exactly the fields its API declares, nothing it did not ask for
  if (plan.pick) out = pickRowFields(out, plan.pick);
  return out;
}

/** Each row with only the fields named (`a,b`); a field the row does not hold stays out. */
function pickRowFields(rows: unknown[], fields: string): unknown[] {
  const keep = fields
    .split(',')
    .map((x) => x.trim())
    .filter(Boolean);
  return rows.map((r) => {
    if (!r || typeof r !== 'object') return r;
    const out: Record<string, unknown> = {};
    for (const k of keep) {
      const v = getPath(r, k);
      if (v !== undefined) out[k] = v;
    }
    return out;
  });
}

/** Each row marked `firstOfRoot`, true for the first row of its `rootId`. */
function markFirstOfRoot(rows: unknown[]): unknown[] {
  const seen = new Set<string>();
  return rows.map((r) => {
    const root = toStr(getPath(r, 'rootId'));
    const first = !seen.has(root);
    seen.add(root);
    return r && typeof r === 'object'
      ? { ...(r as Record<string, unknown>), firstOfRoot: first }
      : r;
  });
}

/**
 * `rows(<rows>[;condition]…)` — the rows of a list that match every
 * condition, in the order the answer gave them.
 *
 *   <path>=<value>     is <value> (`a|b`: one of them)     <path>!=<value>  is not
 *   <path>==<value>    is <value>, as a LOOKUP: with no value there is no row
 *   <path>             holds a value
 *   <path>~=<text>     contains <text>, whatever the case; <path> may name
 *                      several fields (`name|accountNumber`)
 *   <path>>=<value>    at least, `<=` at most; `days:<n>` is the day n days ago
 *                      (`now`: this moment — `expiresAt>=now` keeps what has not run out; no value has not)
 *
 * A condition with an EMPTY value is left out: a filter nobody has set
 * filters nothing, so one path serves a list and the controls above it.
 * `sort=<path>` (`:desc` for largest first) and `top=<n>` order and cut;
 * `pick=<a>,<b>` keeps only those fields of each row.
 *
 * The corporate portal's lists are read whole and narrowed on the page
 * (reference: filterAccounts — "a round trip per keystroke would be slower
 * than the filter it replaces"), and one row of another answer is looked up
 * by a value this one holds (the company a session acts for).
 */
function matchingRows(obj: unknown, args: string[]): unknown[] {
  const [rowsPath = '', ...conditions] = args;
  const at = rowsPath ? getPath(obj, rowsPath) : obj;
  let rows: unknown[] = Array.isArray(at) ? at : [];
  // `via=<path field>:<name field>`: each row belongs under the row its dotted
  // path starts with (an owner path `{group}.{entity}`) and gains `rootId` and
  // `rootName` — the group's name where the group is one of the rows, else the
  // row's own (the reference names a company's group the same way). Read from
  // ALL the rows, before any condition narrows them.
  const via = conditions.find((c) => c.startsWith('via='))?.slice(4) ?? '';
  if (via) rows = addViaRoots(rows, via);
  // `join=<as>:<table>:<key>:<value>:<field>`: each row gains <as> — the <value> of the <table> row whose
  // <key> is this row's <field> (an edge names its holder by id; the name is in another list of the
  // same answer). Several joins fill the same <as> in order: the first table that knows the id wins.
  // `map=<as>:<field>:<A>=<text>~<B>=<text>~*=<text>`: <as> worded from a code, where still empty.
  // `has=<as>:<field>:<word>=<text>~<word>=<text>`: <as> worded from the first <word> the field holds.
  for (const condition of conditions) rows = applyDecorationCondition(obj, rows, condition);
  const { kept, plan } = applyFilterConditions(rows, conditions);
  const shaped = applyRowsReadPlan(kept, plan);
  // with `via=`: the first row of each root says so (a heading above a group of companies)
  return via ? markFirstOfRoot(shaped) : shaped;
}

/**
 * `pages(<count>;<size>)` — the pages of a list, as entries a pager's chips
 * show: `{ key: '0', label: '1' }`, … — <count> is a path to the answer's own
 * total (`count`) or a number. At least one page, so a pager never vanishes
 * under an empty list. `<grouped read>.pages:<size>` counts that read's rows.
 */
function pageEntries(total: number, size: number): GroupRow[] {
  const n = Math.max(1, Math.ceil(Math.max(0, total) / Math.max(1, size)));
  return Array.from({ length: n }, (_, i) => ({
    key: String(i),
    label: String(i + 1),
    total: i,
    count: 0,
    share: 0,
    legend: String(i + 1),
  }));
}

function pageRows(obj: unknown, args: string[]): GroupRow[] {
  const [countPath = '', size = '20'] = args;
  const literal = Number(countPath);
  const total =
    countPath !== '' && Number.isFinite(literal) ? literal : amountNumber(getPath(obj, countPath));
  return pageEntries(total, Math.round(Number(size)) || 20);
}

/**
 * A grouped read's arguments: cut at `;` OUTSIDE any brackets, so the rows a
 * read starts from may themselves be a grouped read — `rows(tree(a;b;c);!parentId)`
 * is "the companies of the tree nobody in it holds".
 */
function topArgs(inside: string): string[] {
  const args: string[] = [];
  let depth = 0;
  let start = 0;
  for (let i = 0; i < inside.length; i += 1) {
    const ch = inside[i];
    if (ch === '(') depth += 1;
    else if (ch === ')') depth = Math.max(0, depth - 1);
    else if (ch === ';' && depth === 0) {
      args.push(inside.slice(start, i).trim());
      start = i + 1;
    }
  }
  args.push(inside.slice(start).trim());
  return args;
}

/**
 * A grouped read, and what follows it: `group(...)` is the entries,
 * `group(...).total` one field of every entry (a chart's values),
 * `group(...)[1].key` one entry's field. Undefined when `path` is not one.
 */
function groupedRead(obj: unknown, path: string): { value: unknown } | undefined {
  const fns: Record<string, (o: unknown, a: string[]) => unknown[]> = {
    group: groupRows,
    months: monthRows,
    rows: matchingRows,
    pages: pageRows,
    tree: treeRows,
    split: splitRows,
  };
  const open = path.indexOf('(');
  const fn = open > 0 ? fns[path.slice(0, open)] : undefined;
  // the LAST bracket: a value being matched may hold one ("Modon (Holding)")
  const close = path.lastIndexOf(')');
  if (!fn || close < open) return undefined;
  const rows = fn(obj, topArgs(path.slice(open + 1, close)));
  const rest = path.slice(close + 1);
  if (!rest) return { value: rows };
  if (rest === '.length') return { value: rows.length };
  // `.pages:<size>` the pager's entries; `.pages:<size>.length` how many pages ("Page 2 of 7")
  if (rest.startsWith('.pages:')) {
    const counted = rest.endsWith('.length');
    const entries = pageEntries(
      rows.length,
      Math.round(Number(counted ? rest.slice(7, -7) : rest.slice(7))) || 20,
    );
    return { value: counted ? entries.length : entries };
  }
  if (rest.startsWith('.')) return { value: rows.map((r) => getPath(r, rest.slice(1))) };
  return { value: getPath(rows, rest) };
}

/** `days:<n>` / `months:<n>` / an ISO date → the calendar day it names ('' for none). */
function boundDay(spec: string): string {
  const t = spec.trim();
  if (t === '') return '';
  if (t.startsWith('days:')) {
    const n = Number(t.slice(5));
    return t.slice(5).trim() === '' || !Number.isFinite(n)
      ? ''
      : new Date(Date.now() - n * 86400000).toISOString().slice(0, 10);
  }
  if (t.startsWith('months:')) {
    const n = Number(t.slice(7));
    if (t.slice(7).trim() === '' || !Number.isFinite(n)) return '';
    const now = new Date();
    return new Date(
      Date.UTC(now.getUTCFullYear(), now.getUTCMonth() - Math.max(0, Math.round(n) - 1), 1),
    )
      .toISOString()
      .slice(0, 10);
  }
  return t.slice(0, 10);
}

/** The total a page of a `gatherPages` read states at `countPath` (a finite number), else the one stated before it. */
function statedPageCount(
  body: unknown,
  cfg: { countPath: string },
  count: number | undefined,
): number | undefined {
  const c = Number(getPath(body, cfg.countPath));
  return Number.isFinite(c) && getPath(body, cfg.countPath) !== undefined ? c : count;
}

/** A page that ends a `gatherPages` read: an empty or short one, or the one that brings in the `count` records stated. */
function lastGatheredPage(
  rows: unknown[],
  size: number,
  held: number,
  count: number | undefined,
): boolean {
  return (
    rows.length === 0 || (size > 0 && rows.length < size) || (count !== undefined && held >= count)
  );
}

/** `until`: a page whose last record is older than `since` — a statement read newest-first is not read past its window. */
function pagePastWindow(rows: unknown[], since: string, cfg: { untilPath?: string }): boolean {
  if (!since || !cfg.untilPath) return false;
  const last = toStr(getPath(rows.at(-1), cfg.untilPath));
  return last !== '' && last.slice(0, since.length) < since;
}

/** The first page's envelope: its own fields when it answered an object (not a list), else none. */
function firstPageEnvelope(first: unknown): Record<string, unknown> {
  return first && typeof first === 'object' && !Array.isArray(first)
    ? (first as Record<string, unknown>)
    : {};
}

/**
 * Every page of a list, gathered — a binding's `pages` (Bindings › "Read every
 * page"). Asks page 0, 1, … with the page size the request already sends and
 * stops on a short page, once `count` records are in, after `max` pages, or —
 * `until` — when the last record of a page is older than `before` (a statement
 * read newest-first is not read past the window it is shown for). Answers the
 * first page's envelope with every record in it.
 */
export async function gatherPages(
  call: (vars: Record<string, unknown>) => Promise<unknown>,
  vars: Record<string, unknown>,
  cfg: {
    max: number;
    pageParam: string;
    recordsPath: string;
    countPath: string;
    untilPath?: string;
  },
  before: string,
): Promise<unknown> {
  const size = Number(vars.pageSize ?? vars.size ?? 0);
  const since = boundDay(before);
  const records: unknown[] = [];
  let first: unknown = undefined;
  let count: number | undefined;
  for (let page = 0; page < Math.max(1, cfg.max); page += 1) {
    const body = await call({ ...vars, [cfg.pageParam]: page });
    if (page === 0) first = body;
    const batch = getPath(body, cfg.recordsPath);
    const rows = Array.isArray(batch) ? batch : [];
    records.push(...rows);
    count = statedPageCount(body, cfg, count);
    if (lastGatheredPage(rows, size, records.length, count) || pagePastWindow(rows, since, cfg))
      break;
  }
  const envelope = firstPageEnvelope(first);
  return { ...envelope, [cfg.recordsPath]: records, [cfg.countPath]: count ?? records.length };
}

/**
 * An answer read TOGETHER WITH others — a binding's `with` (Bindings › "Read together with").
 * The other reads' answers sit beside this one's own fields under the names given, so one path can
 * join them: a share register names its holders by id, and the names are in the company list.
 * Nothing is added until this read has answered (an absent answer stays absent), and an answer
 * that is a bare list is left as it is.
 */
export function withAnswers(data: unknown, extra: Record<string, unknown>): unknown {
  if (!data || typeof data !== 'object' || Array.isArray(data)) return data;
  return { ...(data as Record<string, unknown>), ...extra };
}

/** The values a `forEach` read asks for: one per row of another answer, each once. */
export function gatherKeys(data: unknown, path: string, field: string, max: number): string[] {
  const at = getPath(data, path);
  const rows = Array.isArray(at) ? at : [];
  const keys = rows.map((row) => toStr(getPath(row, field))).filter((k) => k !== '');
  return [...new Set(keys)].slice(0, Math.max(0, max));
}

/**
 * A call made once per value, the answers gathered — a binding's `forEach`
 * (Bindings › "Repeat for each row of"). A company group's relationships are
 * read company by company: the gateway has no group-wide read for a corporate
 * caller. A call that fails costs its own rows, not the others' (the reference
 * reads each one with `.catch(() => null)`). Each record carries `__from`.
 */
export async function gatherEach(
  call: (vars: Record<string, unknown>) => Promise<unknown>,
  vars: Record<string, unknown>,
  param: string,
  keys: string[],
  from: unknown[] = [],
): Promise<unknown> {
  const answers = await Promise.all(
    keys.map((key) =>
      call({ ...vars, [param]: key }).then(
        (body) => ({ key, body }),
        () => ({ key, body: null as unknown }),
      ),
    ),
  );
  const records = answers.flatMap(({ key, body }) => {
    const at = getPath(body, 'records');
    const rows = firstList(at, body);
    return rows.map((row) =>
      row && typeof row === 'object' ? { ...(row as Record<string, unknown>), __from: key } : row,
    );
  });
  // `from`: the rows the calls were made for — a tree reads both (the companies, and the edges between them)
  return { records, count: records.length, from };
}

/** The rows a `forEach` read is made for (its source answer at `path`). */
export function gatherSource(data: unknown, path: string): unknown[] {
  const at = getPath(data, path);
  return Array.isArray(at) ? at : [];
}

/** One `<edge path>=<value>` option of a `tree(…)` read (`a|b`: one of them) against one edge. */
function treeEdgeKept(edge: unknown, option: string): boolean {
  const i = option.indexOf('=');
  const want = option
    .slice(i + 1)
    .split('|')
    .map((x) => x.trim());
  return want.includes(toStr(getPath(edge, option.slice(0, i).trim())));
}

/** The edges at <edges> of a `tree(…)` read that pass every `<edge path>=<value>` option. */
function keptTreeEdges(obj: unknown, edgesPath: string, options: string[]): unknown[] {
  const keep = options.filter(
    (o) => !o.startsWith('pct=') && !o.startsWith('root=') && o.includes('='),
  );
  const edgesAt = edgesPath ? getPath(obj, edgesPath) : [];
  return (Array.isArray(edgesAt) ? edgesAt : []).filter((e) =>
    keep.every((o) => treeEdgeKept(e, o)),
  );
}

/** Holders by share, largest first; a share not recorded (or zero) comes last. */
function byLargerShare(a: { pct: string }, b: { pct: string }): number {
  return (Number(b.pct) || -1) - (Number(a.pct) || -1);
}

/**
 * The holders of each row of a `tree(…)` read: an edge `<from> → <to>` between two
 * of its rows makes <from> a holder of <to>, with the share the edge carries.
 */
function treeHolders(
  edges: unknown[],
  byId: ReadonlyMap<string, unknown>,
  fromPath: string,
  toPath: string,
  pctPath: string,
): Map<string, Array<{ id: string; pct: string }>> {
  const holders = new Map<string, Array<{ id: string; pct: string }>>();
  for (const e of edges) {
    const from = toStr(getPath(e, fromPath));
    const to = toStr(getPath(e, toPath));
    if (!from || !to || from === to || !byId.has(from) || !byId.has(to)) continue;
    const list = holders.get(to) ?? [];
    if (!list.some((h) => h.id === from))
      list.push({ id: from, pct: pctPath ? toStr(getPath(e, pctPath)) : '' });
    holders.set(to, list);
  }
  // the holders of each row, largest share first (a share not recorded comes last)
  for (const list of holders.values()) list.sort(byLargerShare);
  return holders;
}

/** The rows of a `tree(…)` read under each row that holds them (its largest holder), and the rows nobody holds. */
function treeChildren(
  rows: Record<string, unknown>[],
  idPath: string,
  holders: ReadonlyMap<string, Array<{ id: string; pct: string }>>,
): { childrenOf: Map<string, Record<string, unknown>[]>; tops: Record<string, unknown>[] } {
  const childrenOf = new Map<string, Record<string, unknown>[]>();
  const tops: Record<string, unknown>[] = [];
  for (const r of rows) {
    const parent = holders.get(toStr(getPath(r, idPath)))?.[0]?.id ?? '';
    if (parent) childrenOf.set(parent, [...(childrenOf.get(parent) ?? []), r]);
    else tops.push(r);
  }
  return { childrenOf, tops };
}

/** A `tree(…)` read's rows as they are placed (see placeTreeRow). */
interface TreePlacement {
  idPath: string;
  namePath: string;
  byId: ReadonlyMap<string, Record<string, unknown>>;
  holders: ReadonlyMap<string, Array<{ id: string; pct: string }>>;
  childrenOf: ReadonlyMap<string, Record<string, unknown>[]>;
  placed: Set<string>;
  out: unknown[];
}

/** Rows of a `tree(…)` read in name order, as a new list. */
function treeRowsByName(
  rows: Record<string, unknown>[],
  namePath: string,
): Record<string, unknown>[] {
  return [...rows].sort((a, b) =>
    toStr(getPath(a, namePath)).localeCompare(toStr(getPath(b, namePath))),
  );
}

/** A holder's share as `alsoHeldBy` words it: " 30%" (two places at most), '' when none is recorded. */
function heldShareText(pct: string): string {
  return pct === '' ? '' : ' ' + String(Number(Number(pct).toFixed(2))) + '%';
}

/** Places a row of a `tree(…)` read at `depth` under `parentId`, then its children in name order — each row once. */
function placeTreeRow(
  t: TreePlacement,
  r: Record<string, unknown>,
  depth: number,
  parentId: string,
): void {
  const id = toStr(getPath(r, t.idPath));
  if (t.placed.has(id)) return;
  t.placed.add(id);
  const [first, ...rest] = t.holders.get(id) ?? [];
  t.out.push({
    ...r,
    depth,
    parentId,
    parentPct: first?.id === parentId ? first.pct : '',
    alsoHeldBy: rest
      .map(
        (h) =>
          toStr(
            getPath(
              /* v8 ignore next -- a holder is always one of the rows (treeHolders) */ t.byId.get(
                h.id,
              ) ?? {},
              t.namePath,
            ),
          ) + heldShareText(h.pct),
      )
      .join(', '),
  });
  for (const c of treeRowsByName(t.childrenOf.get(id) ?? [], t.namePath))
    placeTreeRow(t, c, depth + 1, id);
}

/**
 * `tree(<rows>;<id>;<name>;<edges>;<from>;<to>[;option]…)` — the rows ordered as
 * a tree, each placed under the row that holds it: an edge `<from> → <to>`
 * (both row ids) makes <from> the parent of <to>. A row held by several is
 * placed under the largest holder (`pct=<edge field>`) and names the others.
 * Siblings in name order, parents before their children. Options:
 *   `<edge path>=<value>`  keep only such edges (`relationshipType=OWNS|SUBSIDIARY_OF`)
 *   `pct=<edge path>`      the share an edge carries
 *   `root=<name>`          one more row on top, holding every row with no parent
 * Each row gains `depth` (0 at the top), `parentId`, `parentPct` and
 * `alsoHeldBy` ("Falak Holding 30%, …"). The corporate reference's group
 * structure, and the companies an access matrix is ticked against.
 */
function treeRows(obj: unknown, args: string[]): unknown[] {
  const [
    rowsPath = '',
    idPath = 'id',
    namePath = 'name',
    edgesPath = '',
    fromPath = 'sourceId',
    toPath = 'targetId',
    ...options
  ] = args;
  const at = rowsPath ? getPath(obj, rowsPath) : obj;
  const rows = (Array.isArray(at) ? at : []).filter((r) => r && typeof r === 'object') as Record<
    string,
    unknown
  >[];
  const byId = new Map(rows.map((r) => [toStr(getPath(r, idPath)), r]));
  const pctPath =
    options
      .find((o) => o.startsWith('pct='))
      ?.slice(4)
      .trim() ?? '';
  const rootName =
    options
      .find((o) => o.startsWith('root='))
      ?.slice(5)
      .trim() ?? '';
  const holders = treeHolders(
    keptTreeEdges(obj, edgesPath, options),
    byId,
    fromPath,
    toPath,
    pctPath,
  );
  const { childrenOf, tops } = treeChildren(rows, idPath, holders);
  const t: TreePlacement = {
    idPath,
    namePath,
    byId,
    holders,
    childrenOf,
    placed: new Set<string>(),
    out: [],
  };
  const base = rootName ? 1 : 0;
  const rootId = rootName ? '__root' : '';
  /* v8 ignore next -- a split has a first part */
  const nameKey = namePath.split('.')[0] ?? 'name';
  if (rootName)
    t.out.push({
      id: '__root',
      [nameKey]: rootName,
      depth: 0,
      parentId: '',
      parentPct: '',
      alsoHeldBy: '',
      isRoot: true,
    });
  for (const r of treeRowsByName(tops, namePath)) placeTreeRow(t, r, base, rootId);
  // a cycle leaves rows unplaced: they go on top rather than vanish
  for (const r of rows) placeTreeRow(t, r, base, rootId);
  return t.out;
}

/** `split(<path>;<separator>)` — a text cut into entries `{ key }` (a request's roles, one chip each). Space by default. */
function splitRows(obj: unknown, args: string[]): GroupRow[] {
  const [path = '', sep = ' '] = args;
  const text = toStr(getPath(obj, path));
  const parts = sep.trim() === '' ? text.split(/\s+/) : text.split(sep);
  return parts
    .map((x) => x.trim())
    .filter(Boolean)
    .map((key) => ({ key, label: key, total: 0, count: 0, share: 0, legend: key }));
}

/** ` ?? ` alternatives OUTSIDE any brackets — a grouped read may hold its own. */
function topAlternatives(path: string): string[] {
  const parts: string[] = [];
  let depth = 0;
  let start = 0;
  for (let i = 0; i < path.length; i += 1) {
    const ch = path[i];
    if (ch === '(') depth += 1;
    else if (ch === ')') depth = Math.max(0, depth - 1);
    else if (depth === 0 && path.startsWith(' ?? ', i)) {
      parts.push(path.slice(start, i));
      start = i + 4;
      i += 3;
    }
  }
  parts.push(path.slice(start));
  return parts;
}

/**
 * Grouped reads as alternatives — `rows(…;id=={param:c})[0] ?? rows(…)[0]`:
 * the company asked for, else the session's own. Undefined when `path` is not
 * one: no bracket, or no ` ?? ` outside its brackets.
 */
function groupedAlternativeRead(obj: unknown, path: string): { value: unknown } | undefined {
  if (!path.includes('(') || !path.includes(' ?? ')) return undefined;
  const alts = topAlternatives(path);
  if (alts.length <= 1) return undefined;
  for (const alt of alts) {
    const v = getPath(obj, alt.trim());
    if (holdsValue(v)) return { value: v };
  }
  return { value: undefined };
}

/** The dotted walk — `a.b[0].c`, a segment at a time (see stepInto); undefined once a step leaves the objects. */
function walkDottedPath(obj: unknown, path: string): unknown {
  let cur: unknown = obj;
  for (const seg of path
    .replaceAll(/\[(\d+)\]/g, '.$1')
    .split('.')
    .filter(Boolean)) {
    if (cur === null || cur === undefined || typeof cur !== 'object') return undefined;
    cur = stepInto(cur, seg);
  }
  return cur;
}

export function getPath(obj: unknown, path: string): unknown {
  // "." is the value itself: a row of a list of plain values ({item:.|words})
  if (!path || path === '.') return obj;
  if (path.startsWith('sumfx(') && path.endsWith(')')) return sumFx(obj, path.slice(6, -1));
  const alternatives = groupedAlternativeRead(obj, path);
  if (alternatives) return alternatives.value;
  const grouped = groupedRead(obj, path);
  if (grouped) return grouped.value;
  if (path.includes(' ?? ')) return firstAlternative(obj, path);
  const star = path.indexOf('[*]');
  if (star >= 0) return firstRowValue(obj, path, star);
  return walkDottedPath(obj, path);
}

/**
 * A bound photo's layer inside its clipping box. Sample rows are uploaded
 * under the design picture's content hash (…/<sha256>.<ext>), so a seeded
 * row draws exactly the crop the design drew for that picture; any other photo
 * (a user's own) covers the box. Parsed without a pattern on the URL's tail —
 * an end-anchored run is a backtracking hotspot (S5852).
 */
export function photoCrop(
  crops: Readonly<Record<string, { left: number; top: number; width: number; height: number }>>,
  uri: unknown,
): {
  style: {
    position: 'absolute';
    left: number;
    top: number;
    width: number | '100%';
    height: number | '100%';
  };
  resizeMode: 'stretch' | 'cover';
} {
  /* v8 ignore next -- a split has a first part */
  const path = toStr(uri).split(/[?#]/)[0] ?? '';
  const file = path.slice(path.lastIndexOf('/') + 1);
  const dot = file.lastIndexOf('.');
  const hash = (dot > 0 ? file.slice(0, dot) : file).toLowerCase();
  const rect = /^[0-9a-f]{64}$/.test(hash) ? crops[hash] : undefined;
  return rect
    ? { style: { position: 'absolute', ...rect }, resizeMode: 'stretch' }
    : {
        style: { position: 'absolute', left: 0, top: 0, width: '100%', height: '100%' },
        resizeMode: 'cover',
      };
}

/**
 * A bound response value being rendered as TEXT.
 *
 * getPath returns `unknown`, and `String(x ?? '')` on an object produces the
 * literal "[object Object]" on screen — which is what shipped whenever a
 * binding pointed one level too high (Sonar S6551 flags exactly this). An array
 * reads as a comma-separated list and an object as JSON: still not what the
 * design wanted, but debuggable instead of meaningless.
 */
export function toStr(v: unknown): string {
  if (v === null || v === undefined) return '';
  if (typeof v === 'string') return v;
  if (typeof v === 'number' || typeof v === 'boolean' || typeof v === 'bigint') return String(v);
  if (Array.isArray(v)) return v.map(toStr).join(', ');
  try {
    return JSON.stringify(v) ?? '';
  } catch {
    return ''; // circular structure — nothing sensible to render
  }
}

/**
 * A bound picture, or the design's own when the value is empty. Screens used to
 * compute this in an inline `(() => { … })()` inside each list row — one more
 * function level, which put rows past Sonar S2004's depth of 4.
 */
export function imageOr<T>(value: unknown, fallback: T): T | { uri: string } {
  const v = toStr(value);
  return v === '' ? fallback : { uri: v };
}

/**
 * A field's or a response's value as the text a design drew, or the design's
 * own text while there is none. Screens used to spell this out inline,
 * `v != null && String(v) !== '' ? String(v) : 'Design text'`, twice per text:
 * each one counted toward the screen's Sonar S3776 complexity.
 */
export function textOr(value: unknown, fallback: string, prefix = ''): string {
  const s = toStr(value);
  return s === '' ? fallback : prefix + s;
}

/**
 * A field the form requires only while it is shown: met when hidden, else when
 * filled. A screen's readiness used to spell each one `(!(shown) || filled)`,
 * and a long form's chain of them pushed the screen component past Sonar
 * S3776 (51 on Beacon's Own Transfer Amount). Both sides only read the form,
 * so evaluating them eagerly here changes nothing.
 */
export function requiredWhen(shown: unknown, met: boolean): boolean {
  return !shown || met;
}

/** Every condition holds (a visibleWhen `all`). */
export function allOf(...conds: unknown[]): boolean {
  return conds.every(Boolean);
}

/** Some condition holds (a visibleWhen `any`). */
export function anyOf(...conds: unknown[]): boolean {
  return conds.some(Boolean);
}

/** A checkbox in the caller's words: `on` when ticked, `off` otherwise (`{widget:id|on:…|off:…}`). */
export function onOff(value: unknown, on: string, off: string): string {
  return value === true ? on : off;
}

/** The row an empty list's preview draws its template with: none. (A .map over [undefined] cost a function level, S2004.) */
// eslint-disable-next-line @typescript-eslint/no-explicit-any -- a list's row is the design's, untyped: the template reads it as the design named it
export const previewItem: any = undefined;

/**
 * The form-errors update that sets one field's message. Screens wrote it inline,
 * `setFormErrors((e0) => ({ ...e0, [field]: message }))`, and inside a
 * passcode screen's second-factor chain that updater was the fifth nested
 * function (Sonar S2004, Beacon v25 Debit x5).
 */
export function withFieldError(
  field: string,
  message: string,
): (errs: Record<string, string>) => Record<string, string> {
  return (errs) => ({ ...errs, [field]: message });
}

/**
 * The form-errors update that adds a whole validation result. Written inline,
 * `setFormErrors((e0) => ({ ...e0, ...errs }))`, it was one function level too
 * many inside a pager page's press handler (Sonar S2004, MINUS x3).
 */
export function withErrors(
  added: Record<string, string>,
): (errs: Record<string, string>) => Record<string, string> {
  return (errs) => ({ ...errs, ...added });
}

/**
 * A request entry that is sent only while the field feeding it is shown. Written
 * inline, `...(shown ? { k: v } : {})`, it was one ternary per gated field in
 * the submit handler: a 40-field form reached cognitive complexity 75 (Sonar
 * S3776), with a redundant Boolean() in each test (S6509).
 */
export function whenShown(shown: unknown, entry: Record<string, unknown>): Record<string, unknown> {
  return shown ? entry : {};
}

// ── (0.4.83) A REQUEST VALUE WITH A SHAPE — the runtime half of the request editor's set of keys, list and typed leaves. The rule is the
// schema's request-shape.ts (shapeKindOf / asTyped / nonEmptyOf / wireTextOf), mirrored here word for word because a generated app carries
// no schema package; the generator's request-shape test proves the two agree over the shared fixtures. The typing rule is THE TABLE MAP'S
// (tableCore.ts jsonMapValue, the schema's), restated here so a screen without a table types its leaves the same way.

/** nothing, inside a shape: undefined, a blank text, a null — a route param the page was not given reads '', an answer's missing field null */
const isNothing = (v: unknown): boolean => v === undefined || v === '' || v === null;
/** a text, a number, a boolean or a bigint — what one value is made of */
const isScalar = (v: unknown): v is string | number | boolean | bigint =>
  typeof v === 'string' || typeof v === 'number' || typeof v === 'boolean' || typeof v === 'bigint';
/** a scalar spelt as text */
const scalarText = (v: string | number | boolean | bigint): string =>
  typeof v === 'string' ? v : String(v);
const isPlainObject = (v: unknown): v is Record<string, unknown> =>
  typeof v === 'object' && v !== null && !Array.isArray(v);

/**
 * A SET OF KEYS with the entries that have a value: an entry that resolved to nothing (undefined, '', null) is left out, as the table
 * map and a hidden field's entry are; none left is nothing — the param is not sent (the client's cleaned() drops it from a query, setByPath
 * skips it in a body). A page opened without its id sends no filter rather than `{"customerId":""}`.
 */
export function dropEmpty(entries: Record<string, unknown>): Record<string, unknown> | undefined {
  const kept = Object.entries(entries).filter(([, v]) => !isNothing(v));
  return kept.length ? Object.fromEntries(kept) : undefined;
}

/** A LIST with the items that have a value; none left is nothing. */
export function compactList(items: readonly unknown[]): unknown[] | undefined {
  const kept = items.filter((v) => !isNothing(v));
  return kept.length ? kept : undefined;
}

/**
 * THE ROWS OF AN ANSWER a list is built from (`from` the rows of a table, any list in an answer): the answer itself when it is a list, else
 * its records / data / items / results / history, else its first list; no answer, or no list in it, is no rows (the table runtime's
 * rowsOfAnswer, for a screen without a table).
 */
export function answerRows(answer: unknown): unknown[] {
  if (Array.isArray(answer)) return answer;
  if (!isPlainObject(answer)) return [];
  for (const k of ['records', 'data', 'items', 'results', 'history']) {
    const at = answer[k];
    if (Array.isArray(at)) return at;
  }
  const first = Object.values(answer).find(Array.isArray);
  return first ?? [];
}

/** A row's item that sends nothing but the item's typed constants is no row — as a repeat section's row holding only its constants is dropped. */
export function keptRow(value: unknown, constants: number): unknown {
  return isPlainObject(value) && Object.keys(value).length <= constants ? undefined : value;
}

/** A list item sent only while the field feeding it is shown — whenShown, for an item rather than an entry. */
export function shownOr(shown: unknown, value: unknown): unknown {
  return shown ? value : undefined;
}

// the typing rule — tableCore.ts jsonMapValue / jsonMapDateRange, the schema's
const DAY_START = 'T00:00:00.000Z';
const DAY_END = 'T23:59:59.999Z';
const ISO_DAY = /^\d{4}-\d{2}-\d{2}$/;
const isDay = (v: string): boolean => {
  if (!ISO_DAY.test(v)) return false;
  const t = new Date(v + DAY_START).getTime();
  return !Number.isNaN(t) && new Date(t).toISOString().slice(0, 10) === v;
};
/** a day filter's value as the core system's range: one day from its start to its end, `from..to` both days, `from..` / `..to` open at one end; a day that is no day, or a range running backwards, is null */
function dayRange(text: string): Record<string, unknown> | null {
  // the text comes trimmed and non-blank (typedText reads emptiness first)
  const sep = text.includes('..') ? '..' : ',';
  const parts = text.includes(sep) ? text.split(sep) : [text, text];
  if (parts.length !== 2) return null;
  const [first = '', second = ''] = parts;
  const from = first.trim();
  const to = second.trim();
  if ((from && !isDay(from)) || (to && !isDay(to)) || (from && to && from > to)) return null;
  if (from && to) return { between: [from + DAY_START, to + DAY_END] };
  if (from) return { gte: from + DAY_START };
  return to ? { lte: to + DAY_END } : null;
}
const listOf = (text: string): string[] =>
  text
    .split(',')
    .map((v) => v.trim())
    .filter(Boolean);
/** the numbers among some values: one alone, several as a list, none as nothing (a boolean is no number) */
const numbersOf = (items: readonly unknown[]): unknown => {
  const numbers = items
    .filter((v) => typeof v !== 'boolean')
    .map(Number)
    .filter((n) => Number.isFinite(n));
  if (!numbers.length) return undefined;
  return numbers.length === 1 ? numbers[0] : numbers;
};
/** a text read as its kind: text trimmed; a number (several by commas: a list of numbers); a list by commas; a boolean word; a day range; nothing for a blank or what does not read */
function typedText(value: string, as: string): unknown {
  const text = value.trim();
  if (!text) return undefined;
  if (as === 'text') return text;
  if (as === 'list') {
    const list = listOf(text);
    return list.length ? list : undefined;
  }
  if (as === 'number') return numbersOf(listOf(text));
  if (as === 'boolean') {
    const word = text.toLowerCase();
    if (word === 'true') return true;
    return word === 'false' ? false : undefined;
  }
  return dayRange(text) ?? undefined;
}

/**
 * A LEAF'S VALUE TYPED AS ITS `as` SAYS (schema 0.4.83): no `as` is a pass-through; nothing (undefined, null) stays nothing; a text is read by
 * the rule; a number, a boolean or a bigint is spelt first, then read; a list of scalars is joined by commas, then read; an object, or a list
 * holding one, is kept as it is (typing is for texts). A text that does not read as its kind is nothing, as a blank filter is.
 */
export function asTyped(raw: unknown, as?: string): unknown {
  if (as === undefined) return raw;
  if (raw === undefined || raw === null) return undefined;
  if (typeof raw === 'string') return typedText(raw, as);
  if (Array.isArray(raw))
    return raw.every(isScalar) ? typedText(raw.map((v) => scalarText(v)).join(','), as) : raw;
  if (isPlainObject(raw)) return raw;
  // a number, a boolean or a bigint, spelt then read; nothing else reaches a mapping's leaf
  return isScalar(raw) ? typedText(scalarText(raw), as) : undefined;
}

/** a bigint spelt as text in JSON (JSON has no word for it), as the client's path encoding spells it */
const jsonText = (value: unknown): string =>
  JSON.stringify(value, (_key, v: unknown) => (typeof v === 'bigint' ? String(v) : v));
/** a list of scalars comma-joined (wireShape says every item is one) */
const commaJoined = (list: readonly unknown[]): string =>
  list.filter(isScalar).map(scalarText).join(',');
/** the shape of a value already resolved: a plain object a set of keys; a list of scalars, else a list of objects (a list of lists goes as JSON too); the rest one value */
function wireShape(value: unknown): 'value' | 'object' | 'scalarList' | 'objectList' {
  if (Array.isArray(value)) return value.every(isScalar) ? 'scalarList' : 'objectList';
  return isPlainObject(value) ? 'object' : 'value';
}
/** a value with its emptiness read, one level deep: '' , a set of keys with no entries, a list with no items are nothing; an entry or item that is nothing is left out first */
function nonEmpty(value: unknown): unknown {
  if (value === undefined || value === '') return undefined;
  if (Array.isArray(value)) return compactList(value);
  return isPlainObject(value) ? dropEmpty(value) : value;
}

/**
 * WHAT GOES ON THE WIRE for a param's value at a location — the schema's wireTextOf, every cell: a query takes a set of keys as JSON text in the
 * one param (the core system's "Stringified JSON filter map"), a list of scalars as the list (the client repeats the key, `code=a&code=b`), a
 * list of objects as JSON text; a path takes one value only (a set of keys or a list is refused: nothing); a header or a cookie takes a set
 * of keys as JSON text, a list of scalars comma-joined (a header cannot repeat), a list of objects as JSON text; a JSON body takes the value as it
 * is; a form body takes a set of keys or a list of objects as JSON text under the key, a list of scalars comma-joined. Emptiness first.
 */
export function wireText(
  value: unknown,
  where: 'path' | 'query' | 'header' | 'body' | 'cookie',
  encoding: 'json' | 'form' = 'json',
): unknown {
  const v = nonEmpty(value);
  if (v === undefined) return undefined;
  const shape = wireShape(v);
  if (shape === 'value') return v;
  if (where === 'path') return undefined;
  if (where === 'body' && encoding === 'json') return v;
  if (shape === 'scalarList') return where === 'query' ? v : commaJoined(v as readonly unknown[]);
  return jsonText(v);
}

/** A picture named by a route param: a bundled asset, a URL, or the design's fallback. */
export function assetOr<T>(
  value: unknown,
  fallback: T,
  bundled: Readonly<Record<string, T>>,
): T | { uri: string } {
  const v = toStr(value);
  if (v === '') return fallback;
  return bundled[v] ?? { uri: v };
}

/** The selected position of a chip, tile or segmented group: the index the
 * control recorded when pressed, else where the stored label sits among the
 * options, else the design's default. One call instead of the nested ternary
 * every group used to inline (Sonar S3358). */
export function pickedIndex(
  recorded: unknown,
  options: readonly string[],
  label: unknown,
  fallback: number,
): number {
  if (typeof recorded === 'number') {
    // The index is what a TAP recorded. A value written from elsewhere since —
    // another chip's "also sets", a button that sets this group — names a
    // different option, and the group has to show it: the Savings Hub opened on
    // "Reserve" still painted "Goals", the tab last tapped (v48).
    const named = typeof label === 'string' && label !== '' ? options.indexOf(label) : -1;
    return named >= 0 && options[recorded] !== label ? named : recorded;
  }
  return optionIndex(label, [options], fallback);
}

/** Where `value` sits in the first list that has it, else the fallback — a
 * route param may name an option by its label OR by the value it stands for. */
export function optionIndex(
  value: unknown,
  lists: readonly (readonly string[])[],
  fallback: number,
): number {
  const v = toStr(value);
  for (const list of lists) {
    const at = list.indexOf(v);
    if (at !== -1) return at;
  }
  return fallback;
}

/** A bound response value being used as a LIST (dropdown options, a list's
 * item array). Arrays pass through; null/undefined read as empty.
 *
 * A SCALAR becomes a one-element list instead of throwing. An authored binding
 * path can legitimately land on a single value where the design expects the
 * whole column — `data[0].walletId` reaches one wallet id, not the array of
 * them — and `.map()` on that string crashed the whole screen with
 * "…map is not a function". One option is a truthful rendering of one value;
 * a runtime TypeError is not. */
// eslint-disable-next-line @typescript-eslint/no-explicit-any -- a list's rows are the design's, untyped (see previewItem)
export function asList(v: unknown): any[] {
  if (Array.isArray(v)) return v;
  return v === null || v === undefined ? [] : [v];
}

/** Rows of n, for a bound GRID that cannot use a FlatList's numColumns — one
 * inside the page's own scroller, where a nested vertical VirtualizedList
 * breaks windowing and fights the page for the drag. The last row is short
 * when the data does not divide evenly, exactly as the static grid's chunking
 * leaves it. A column count below 1 would loop forever, so it is floored. */
export function chunk<T>(list: T[], n: number): T[][] {
  const size = Math.max(1, Math.floor(n));
  const out: T[][] = [];
  for (let i = 0; i < list.length; i += size) out.push(list.slice(i, i + size));
  return out;
}

/** A control on the page that narrows a list (the list's props.filterBy): a search box, or a choice — chips, a select. */
export interface RowFilter {
  kind: 'search' | 'choice';
  widgetId: string;
  /** the option that means every row (All, All levels) */
  allLabel?: string;
}

/** What breaks a shown text into words: spaces, separators (· • | / ,), dashes and punctuation. */
const WORD_BREAK = /[\s·•|/,()–—:;.!?_-]+/;

/** A text as its words, case-folded and single-spaced, with a space at each end: "4-Week Fat Loss" is " 4 week fat loss ". */
function spacedWords(text: string): string {
  const words = text
    .toLowerCase()
    .split(WORD_BREAK)
    .filter((w) => w !== '');
  return words.length > 0 ? ' ' + words.join(' ') + ' ' : '';
}

/** The answers one control holds now, case-folded; its all option and blanks are no answer. */
function filterAnswers(f: RowFilter, value: unknown): string[] {
  const all = (f.allLabel ?? '').trim().toLowerCase();
  const raw = Array.isArray(value) ? value.map(toStr) : [toStr(value)];
  return raw.map((v) => v.trim().toLowerCase()).filter((v) => v !== '' && v !== all);
}

/**
 * Whether a row stays while the page's search boxes and choices say what they say now (a list's props.filterBy).
 * `words` are what the row shows: its static cells, or the values its template draws. Every control must agree,
 * and one with no answer yet (or on its all option) lets every row through — the page opens as designed. A search
 * keeps a row where one of its words holds the typed text, case-folded with spaces taken out of both sides, as a
 * binding's search does; a choice keeps a row showing the chosen option as WHOLE words — "Beginner" in "4 weeks ·
 * Beginner", "Fat Loss" in "4-Week Fat Loss", never "Free" in "Freestyle" — and several chosen options keep a row
 * showing any of them.
 */
export function rowPasses(
  form: Record<string, unknown>,
  filters: readonly RowFilter[],
  words: readonly unknown[],
): boolean {
  const texts = words
    .map((w) => toStr(w).toLowerCase())
    .filter((t) => t !== '' && !t.startsWith('asset:'));
  return filters.every((f) => {
    const answers = filterAnswers(f, form[f.widgetId]);
    if (answers.length === 0) return true;
    if (f.kind === 'search') {
      const q = answers.join('').replaceAll(' ', '');
      return texts.some((t) => t.replaceAll(' ', '').includes(q));
    }
    const shown = texts.map(spacedWords);
    return answers.some((a) => {
      const wanted = spacedWords(a);
      return wanted !== '' && shown.some((t) => t.includes(wanted));
    });
  });
}

/** A shown amount as a number: "$40" is 40, "1,299 kr" is 1299, 12.5 stays
 * 12.5. Commas are thousands separators, the same reading the importer used
 * to decide the design's total added up. Anything unreadable counts as 0, so
 * one bad row cannot blank the whole total. */
export function amountOf(v: unknown): number {
  if (typeof v === 'number') return Number.isFinite(v) ? v : 0;
  const n = Number(
    toStr(v)
      .replaceAll(',', '')
      .replaceAll(/[^0-9.-]/g, ''),
  );
  return Number.isFinite(n) ? n : 0;
}

/** A total printed the way the design printed its sample ("$" + 423). A
 * whole number keeps the design's decimals; a fractional one shows at least
 * two, because rounding money away is worse than an extra ".50". */
export function fmtTotal(n: number, prefix: string, suffix: string, decimals: number): string {
  const d = Number.isInteger(n) ? decimals : Math.max(decimals, 2);
  return prefix + n.toFixed(d) + suffix;
}

/**
 * How far a bound list moves what the design draws below it: the rows past the
 * drawn ones, one step each, or the whole drawn run back up when there are none.
 * Nothing moves until the list has loaded, so the design's sample rows keep
 * their place. A named call where screens used to inline an arrow called on the
 * spot (S7743); the loaded check rides in with it, because a ternary around
 * every moved widget put twenty-odd points on one screen (S3776).
 */
export function listGrowth(
  rows: number,
  drawn: number,
  step: number,
  empty: number,
  loaded = true,
): number {
  if (!loaded) return 0;
  return rows > 0 ? (rows - drawn) * step : -empty;
}

/**
 * A picker row as drawn chosen when its index is the picked one (the design's
 * own pick until someone picks), else as drawn resting. One call per row where
 * each row used to inline a ternary: forty rows scored forty (S3776).
 */
export function pickedRow<T>(
  picked: unknown,
  designIndex: number,
  index: number,
  chosen: T,
  resting: T,
): T {
  return (picked ?? designIndex) === index ? chosen : resting;
}

/**
 * A row of a picker that takes SEVERAL answers: drawn chosen while its index is in the picked set (the design's
 * own set until someone picks), else drawn resting. Stillpoint's goal grid draws three goals chosen.
 */
export function pickedRowIn<T>(
  picked: unknown,
  designSet: readonly number[],
  index: number,
  chosen: T,
  resting: T,
): T {
  const set: readonly unknown[] = Array.isArray(picked) ? picked : designSet;
  return set.includes(index) ? chosen : resting;
}

/** The indices a control of several answers holds: what was picked, else the design's own set. */
export function pickedSetOf(picked: unknown, designSet: readonly number[]): number[] {
  return Array.isArray(picked)
    ? picked.filter((n): n is number => typeof n === 'number')
    : [...designSet];
}

/** The picked set after a tap on row index: a picked row is let go, another is added, in the rows' order. */
export function toggledPick(
  picked: unknown,
  designSet: readonly number[],
  index: number,
): number[] {
  const set = pickedSetOf(picked, designSet);
  return set.includes(index)
    ? set.filter((j) => j !== index)
    : [...set, index].sort((a, b) => a - b);
}

/**
 * What a picker or a chip group SENDS (schema 0.4.101 widgetValue.picked): the words it shows chosen, not its index.
 * cells are each option's words (a picker's column, a chip group's items); the form holds indices or words; untouched,
 * the design's own choice. One answer gives one word, several the list in the options' order; none gives nothing.
 */
export function pickedOf(
  value: unknown,
  cells: readonly string[],
  design: number | readonly number[] | undefined,
  many: boolean,
): string | string[] | undefined {
  const chosen = value ?? design;
  const list: unknown[] = Array.isArray(chosen) ? chosen : [chosen];
  const at = new Set<number>();
  for (const v of list) {
    if (typeof v === 'number') at.add(v);
    else if (typeof v === 'string') at.add(cells.indexOf(v));
  }
  const words = cells.filter((c, i) => at.has(i) && c !== '');
  if (many) return words.length > 0 ? words : undefined;
  return words[0];
}

/** A day strip's week as a Monday — any day of it (YYYY-MM-DD), else this week. */
function stripMonday(week: unknown): Date {
  const t = typeof week === 'string' ? week.trim() : '';
  const bare = /^(\d{4})-(\d{2})-(\d{2})/.exec(t);
  const at = bare ? new Date(Number(bare[1]), Number(bare[2]) - 1, Number(bare[3])) : new Date();
  return new Date(at.getFullYear(), at.getMonth(), at.getDate() - ((at.getDay() + 6) % 7));
}

function stripIso(d: Date): string {
  return (
    d.getFullYear() +
    '-' +
    String(d.getMonth() + 1).padStart(2, '0') +
    '-' +
    String(d.getDate()).padStart(2, '0')
  );
}

/**
 * A DAY STRIP (props.dateStrip, Stillpoint's journal QA 20/11): a picker whose rows are the days of a week. Its value
 * is the tapped day (YYYY-MM-DD), the week its "<id>:week" — any day of it, '' this week. stripDay is the day a tap on
 * row index chooses.
 */
export function stripDay(week: unknown, index: number): string {
  const m = stripMonday(week);
  return stripIso(new Date(m.getFullYear(), m.getMonth(), m.getDate() + index));
}

/** Is row index the chosen day: the tapped day; before any tap, today when the shown week holds it. */
export function dayPicked(value: unknown, week: unknown, index: number): boolean {
  const day = stripDay(week, index);
  return typeof value === 'string' && value !== '' ? value === day : day === stripIso(new Date());
}

/** A day strip's row drawn in its state: chosen (dayPicked), else resting. */
export function dayRow<T>(value: unknown, week: unknown, index: number, chosen: T, resting: T): T {
  return dayPicked(value, week, index) ? chosen : resting;
}

/** The strip's week moved by whole weeks (an arrow, props.shiftsWeek), as its Monday. */
export function weekShift(week: unknown, by: number): string {
  return stripDay(week, 7 * by);
}

/** The design's sample rows while a bound list is empty and has not loaded, else nothing. */
export function samplesWhileEmpty<T>(rows: number, loaded: boolean, samples: T): T | null {
  return rows === 0 && !loaded ? samples : null;
}

/** A computed total as text: a whole number bare, anything else to two places. */
export function numText(v: number): string {
  return Number.isInteger(v) ? String(v) : v.toFixed(2);
}

/** A row's quantity as rendered: negatives clamp to 0, a missing or unreadable one counts once. */
export function qtyOf(n: number): number {
  return Number.isFinite(n) ? Math.max(0, n) : 1;
}

/** A cart's total with the design's fee and discount: nothing when the cart is empty, never below 0. */
export function totalWithFees(sum: number, fee: number, discount: number): number {
  return sum > 0 ? Math.max(0, sum + fee - discount) : 0;
}

/** The moment a value names, in ms; NaN when it names none. */
function momentOf(v: unknown): number {
  return Date.parse(toStr(v));
}

/** A moment the value names that has come (now included): "start again" once a quote lapses. */
export function momentPassed(v: unknown): boolean {
  const t = momentOf(v);
  return !Number.isNaN(t) && t <= Date.now();
}

/** A moment the value names that is still ahead: the cooling-off pill. */
export function momentAhead(v: unknown): boolean {
  return momentOf(v) > Date.now();
}

/** A moment still ahead and no further off than `days`: a document "expiring soon". */
export function momentWithinDays(v: unknown, days: number): boolean {
  const t = momentOf(v);
  return t > Date.now() && t - Date.now() <= days * 86400000;
}

/** Truthiness of an API value bound to a checkbox/switch. JSON booleans pass
 * straight through; the string flags APIs really send ("false", "0", "N",
 * "no") would all be truthy under a plain Boolean(), so they are spelled out.
 * The designer preview mirrors this exactly. */
export function boolish(v: unknown): boolean {
  if (typeof v === 'string') {
    const s = v.trim().toLowerCase();
    return !(s === '' || s === 'false' || s === '0' || s === 'n' || s === 'no');
  }
  return Boolean(v);
}

/*
 * The four helpers below each replace an expression a screen used to spell out
 * at every site. Inline, each was a ternary or a branch counted against the
 * SCREEN's cognitive complexity (S3776) — once per bound switch, per gated
 * widget that keeps its space, per polled status — so a design with enough of
 * them failed the gate with nothing wrong in any one of them.
 */

/** A bound checked state, or the design's own when the response omits the
 * field (null / undefined) — never silently forced off. */
export function boolishOr(v: unknown, fallback: boolean): boolean {
  return v == null ? fallback : boolish(v);
}

/** A widget hidden WITHOUT giving up its space: invisible and untouchable
 * while `shown` is false, laid out the same either way.
 *
 * Never collapsable. Hidden, the box is a real view (opacity and pointerEvents
 * make it one); shown, it had nothing of its own and Android flattened it, so
 * every flip moved its children between it and its parent. A screen whose read
 * flips it on focus (a Dashboard refetching) while a stack reset tears that
 * screen down got an insert of a child still in its old parent: Fabric's
 * "addViewAt … The specified child already has a parent", a red screen. Kept a
 * view either way, nothing moves.
 *
 * A real view needs a real box. Around an ABSOLUTE widget the gate has no size
 * of its own (the widget is out of its flow), and Android leaves what a
 * zero-size view holds out of the accessibility tree: the widget drew, but
 * TalkBack and uiautomator could not reach it (a loan offer's "Financing
 * contract" row). Such a gate is given keptFill — its parent's whole box, the
 * frame an absolute widget is placed in anyway — and the widget's zIndex, so it
 * stacks as it did unwrapped.
 *
 * Hidden from screen readers while hidden: content drawn at opacity 0 is not
 * on screen to anyone. */
export function keptSpace(
  shown: unknown,
  box?: KeptBox,
): {
  style: KeptBox | [KeptBox, { opacity: number }] | { opacity: number } | undefined;
  pointerEvents: 'box-none' | 'none';
  collapsable: false;
  importantForAccessibility: 'auto' | 'no-hide-descendants';
  accessibilityElementsHidden: boolean;
} {
  if (shown) {
    return {
      style: box,
      pointerEvents: 'box-none',
      collapsable: false,
      importantForAccessibility: 'auto',
      accessibilityElementsHidden: false,
    };
  }
  return {
    style: box ? [box, { opacity: 0 }] : { opacity: 0 },
    pointerEvents: 'none',
    collapsable: false,
    importantForAccessibility: 'no-hide-descendants',
    accessibilityElementsHidden: true,
  };
}

/** The box a gate around an absolute widget takes: its parent's (see keptSpace). */
export type KeptBox = {
  position: 'absolute';
  top: number;
  left: number;
  right: number;
  bottom: number;
  zIndex?: number;
};
export const keptFill: KeptBox = { position: 'absolute', top: 0, left: 0, right: 0, bottom: 0 };

/** The value of the first arm whose condition holds, else null. Every
 * condition is a pure read of state already in hand, so evaluating them all
 * costs nothing and keeps the choice one flat list. */
export function firstWhen<T>(arms: ReadonlyArray<readonly [unknown, T]>): T | null {
  for (const [when, then] of arms) if (when) return then;
  return null;
}

/**
 * The status a polled read hands its response rules — or null while the poll
 * should keep waiting.
 *
 * `seen` counts the answers (a new data or error stamp is a new answer). A
 * read that succeeded without reaching one of `plan.done` waits, until
 * `plan.max` answers have come back, when it is reported as a time-out
 * (408); an error, or an answer that is done, is reported as it came.
 */
export function pollVerdict(
  q: { isSuccess: boolean; dataUpdatedAt: number; errorUpdatedAt: number },
  settledRead: { body: unknown; status: number },
  seen: { current: { n: number; at: string } },
  plan: { path: string; done: readonly string[]; max: number; notFoundPending?: boolean },
): number | null {
  const stamp = String(q.dataUpdatedAt) + ':' + String(q.errorUpdatedAt);
  if (stamp !== seen.current.at) seen.current = { n: seen.current.n + 1, at: stamp };
  const v =
    getPath(settledRead.body, plan.path) ??
    getPath((settledRead.body as { data?: unknown } | null)?.data, plan.path);
  const done = typeof v === 'string' && plan.done.includes(v);
  const waiting = q.isSuccess || (plan.notFoundPending === true && settledRead.status === 404);
  if (!waiting || done) return settledRead.status;
  return seen.current.n >= plan.max ? 408 : null;
}

/**
 * Ask a polled read again, for a read the screen fires itself: React Query
 * keeps no refetchInterval for a query that is not enabled. Run from an effect
 * on the read's answers: an answer that is not one of plan.done is asked again
 * after plan.delayMs, for at most plan.max answers. An answer the screen asked
 * for (a focus, a press, a chain) starts a new wait; an error ends it. Returns
 * the timer's cleanup.
 */
export function pollAgain(
  q: { isSuccess: boolean; isFetching: boolean; data?: unknown; refetch: () => Promise<unknown> },
  seen: { current: { n: number; mine: boolean } },
  plan: { path: string; done: readonly string[]; max: number; delayMs: number },
): (() => void) | undefined {
  if (!q.isSuccess || q.isFetching) return undefined;
  seen.current = { n: seen.current.mine ? seen.current.n + 1 : 1, mine: false };
  const v =
    getPath(q.data, plan.path) ?? getPath((q.data as { data?: unknown } | null)?.data, plan.path);
  if ((typeof v === 'string' && plan.done.includes(v)) || seen.current.n >= plan.max)
    return undefined;
  const t = setTimeout(() => {
    seen.current.mine = true;
    q.refetch().catch(() => undefined);
  }, plan.delayMs);
  return () => clearTimeout(t);
}

/** Body and HTTP status of a settled query, whichever way it settled.
 * Response rules are matched against exactly this pair on every screen, and
 * spelling the ternaries out at each site is what pushed a busy screen past the
 * cognitive-complexity limit. */
export function settled(q: { isSuccess: boolean; data?: unknown; error?: unknown }): {
  body: unknown;
  status: number;
} {
  if (q.isSuccess) {
    // no assertion: data is already unknown here, unlike at the call sites
    // this replaced, where react-query had given it a concrete type
    return { body: q.data, status: resStatus(q.data) };
  }
  return {
    body: parseErrorBody(q.error),
    status: (q.error as { status?: number } | null)?.status ?? 0,
  };
}

/**
 * A failed call's HTTP status is one of `codes` — a number, or a class: "4xx" (the service refused,
 * and said why) / "5xx" (it could not answer). 0 is no answer at all (offline, a timeout).
 */
export function failedWith(error: unknown, codes: Array<number | string>): boolean {
  const status = Number((error as { status?: number } | null)?.status ?? 0);
  return codes.some((c) =>
    typeof c === 'number' ? status === c : Math.floor(status / 100) === Number(c.charAt(0)),
  );
}

/*
 * The visibleWhen forms below were spelt inline as `&&` chains. A hidden line
 * repeats its condition in every line below it, so each copy cost the screen
 * a point of cognitive complexity (S3776: 33 on fourteen lines). One call each.
 */

/** A call that failed with one of `codes` (`{ bindingId, state: 'failed', status }`). */
export function failedAs(
  call: { isError: boolean; error: unknown },
  codes: Array<number | string>,
): boolean {
  return call.isError && failedWith(call.error, codes);
}

/** A watched call that stopped asking without the answer it waits for: answered, not settled at `path`, and nothing heard for `ms` (`{ state: 'gaveUp' }`). */
export function gaveUp(
  call: { isSuccess: boolean; isFetching: boolean; data: unknown; dataUpdatedAt: number },
  path: string,
  until: string[],
  ms: number,
): boolean {
  return (
    call.isSuccess &&
    !call.isFetching &&
    !until.includes(toStr(getPath(call.data, path))) &&
    Date.now() - call.dataUpdatedAt > ms
  );
}

/** Two numbers compared by a visibleWhen `op`; false when either is not a number (an empty field, a balance still loading). */
export function numCompare(l: number, op: 'gt' | 'gte' | 'lt' | 'lte' | 'eq', r: number): boolean {
  if (!Number.isFinite(l) || !Number.isFinite(r)) return false;
  switch (op) {
    case 'gt':
      return l > r;
    case 'gte':
      return l >= r;
    case 'lt':
      return l < r;
    case 'lte':
      return l <= r;
    default:
      return l === r;
  }
}

/** Real HTTP status of a SUCCESS response: apiFetch stamps it on object
 * bodies as a non-enumerable __status (a 201/202/204 would otherwise be
 * indistinguishable from 200 once axios unwraps res.data). */
export function resStatus(body: unknown, fallback = 200): number {
  const st =
    body && typeof body === 'object' ? (body as { __status?: unknown }).__status : undefined;
  return typeof st === 'number' ? st : fallback;
}

/** Best-effort response body from a thrown error: AppError keeps the raw
 * HTTP body (a JSON string) on cause.body — parse it so body-path rules can
 * read fields of error responses too. */
export function parseErrorBody(err: unknown): unknown {
  const e = err as { cause?: { body?: unknown } | null; body?: unknown; message?: unknown } | null;
  const raw = e?.cause?.body ?? e?.body;
  if (typeof raw === 'string') {
    try {
      return JSON.parse(raw);
    } catch {
      return raw;
    }
  }
  return raw ?? e?.message;
}

/** The text at a designer-chosen path ("Message from response") of a failed
 * call's body, or '' when it is not text or a number — an object there
 * (Auth0's weak-password `description`) would otherwise render as its JSON,
 * so the caller falls back to errorMessage() instead. */
export function errorTextAt(err: unknown, path: string): string {
  const v = getPath(parseErrorBody(err), path);
  if (typeof v === 'string') return v.trim() ? v : '';
  return typeof v === 'number' ? String(v) : '';
}

/**
 * Land on a screen by REBUILDING the stack, not pushing onto it.
 *
 * A step that completes must not leave the screens that performed it behind:
 * after a sign-in hand-off returns, pushing the next step leaves the browser
 * and its waiting screen underneath, and Back walks the user into a finished
 * flow that re-fires a one-time code.
 *
 * resetTo names the screen the target sits ON TOP OF, so Back reaches a
 * sensible place instead of exiting; '' makes the target the only entry.
 */
export function ruleReset(
  navigation: { reset: (s: unknown) => void },
  target: string,
  resetTo: string | undefined,
  params?: unknown,
): void {
  const routes = resetTo
    ? [{ name: resetTo }, { name: target, params }]
    : [{ name: target, params }];
  if (__DEV__) console.log('[Test] rule.reset stack=' + routes.map((r) => r.name).join(' > '));
  navigation.reset({ index: routes.length - 1, routes });
}

/**
 * The value a rule is tested against.
 *
 * ENVELOPE TOLERANCE: many APIs wrap payloads as `{ data: {...} }`, so when the
 * path misses on the raw body it is retried against `body.data` — rule paths and
 * response-binding paths then accept the same spelling. Both readers below went
 * through their own copy of this; one of them is a rule match and the other is
 * the same rule's target, and they must never disagree about what "actual" is.
 */
function ruleActual(r: ResponseRule, body: unknown, status: number): unknown {
  if (r.source === 'status') return status;
  const path = r.path ?? '';
  const direct = getPath(body, path);
  if (direct !== undefined) return direct;
  const envelope =
    body !== null && typeof body === 'object' && 'data' in (body as Record<string, unknown>)
      ? (body as Record<string, unknown>).data
      : undefined;
  return envelope === undefined ? undefined : getPath(envelope, path);
}

/**
 * A rule's passing message, worded from the response that matched: `{path}` is a field of it,
 * `{path|fallback}` says the fallback where the field is absent.
 */
export function ruleText(text: string, body: unknown): string {
  return text.replaceAll(
    /\{([^{}|]+)(?:\|([^{}]*))?\}/g,
    (_m: string, path: string, fallback?: string) => {
      const value = toStr(getPath(body, path.trim()));
      return value === '' ? (fallback ?? '') : value;
    },
  );
}

/** Did a matched rule take the response over? Then the caller's own success or
 * error handling must not also run — one response, one outcome. */
export function ruleHandled(rule: ResponseRule): boolean {
  // a STAY rule takes the response over too — its outcome is "nothing happens", so the
  // caller's own navigation or failure message must not run either
  return Boolean(
    rule.stay ||
      rule.navigateTo ||
      rule.callBindingId ||
      rule.callActionId ||
      rule.openModalId ||
      rule.alert,
  );
}

/** the cap on calls chained by rules in one go: a ring of rules calling each other stops here */
export const CHAIN_CAP = 12;

/** one hop of a chain — the runner the matched rule names, run while the cap allows, the hop counted */
export function hopChain(hops: { current: number }, run: (() => void) | undefined): void {
  if (hops.current >= CHAIN_CAP) return;
  hops.current += 1;
  run?.();
}

/** a fresh user action — a press, a return to the screen, a table's next job — starts a new chain budget */
export function startChain(hops: { current: number }): void {
  hops.current = 0;
}

/**
 * Everything about a rule's navigation that only the SCREEN knows.
 *
 * Passed as DATA and function references, never as an inline callback: the rule
 * handler that calls ruleNav is already two or three closures deep (a press, a
 * promise, a mutation callback), and one more arrow there is a fifth level of
 * nested functions — which is a finding of its own (S2004) and, worse, reads
 * like the tangle it replaced.
 */
export interface RuleNavPlan {
  method: 'navigate' | 'replace';
  /** Screen names that are FLOW OUTCOMES — a real screen only at runtime. */
  flows?: readonly string[];
  /** The screen's own resolveScreenFlow. Handed in rather than imported: this
   * module is the branching logic and must not depend on navigation. */
  resolveFlow?: (intended: string) => Promise<string>;
  /** goTo from ../navigation/tabs, when the app folds screens into a tab group
   * — it rewrites a tab member into its nested form. Absent otherwise. */
  goTo?: (
    navigation: unknown,
    method: 'navigate' | 'replace',
    name: string,
    params?: never,
  ) => void;
  /** goReset from ../navigation/tabs, present for the same reason goTo is.
   * A reset needs it for a second reason on top of folding tab members: the
   * reset must run on the ROOT navigator, and a screen inside the tabs holds
   * the tab navigator, which owns none of those routes. */
  goReset?: (navigation: unknown, routes: Array<{ name: string; params?: unknown }>) => void;
  params?: unknown;
}

function goRuleTarget(navigation: unknown, plan: RuleNavPlan, target: string): void {
  if (plan.goTo) plan.goTo(navigation, plan.method, target, plan.params as never);
  else
    (navigation as Record<string, (n: string, p?: unknown) => void>)[plan.method]?.(
      target,
      plan.params,
    );
}

/**
 * A matched rule's navigation: REBUILD the stack when it carries resetTo, push
 * otherwise. The decision is made at runtime, not at emit time — one rule list
 * mixes both kinds (a UAE PASS success resets onto the chooser while a rejection
 * on the same list just navigates).
 *
 * This used to be spelled out at every rule handler on every screen: the
 * navigateTo test, the resetTo test, its else, and the flow-outcome test inside
 * it. Four branches per binding, in the busiest function on the screen.
 */
export function ruleNav(
  rule: ResponseRule,
  navigation: { reset: (s: unknown) => void },
  plan: RuleNavPlan,
): void {
  const target = rule.navigateTo;
  if (!target) return;
  if (rule.resetTo !== undefined) {
    // In tabs mode goReset already folds a tab member into its group AND
    // walks up to the root navigator. Without it, naming a tab screen here
    // throws "The action 'RESET' was not handled by any navigator".
    if (plan.goReset) {
      const routes = rule.resetTo
        ? [{ name: rule.resetTo }, { name: target, params: plan.params }]
        : [{ name: target, params: plan.params }];
      if (__DEV__) console.log('[Test] rule.reset stack=' + routes.map((r) => r.name).join(' > '));
      plan.goReset(navigation, routes);
      return;
    }
    ruleReset(navigation, target, rule.resetTo, plan.params);
    return;
  }
  if (plan.resolveFlow && plan.flows?.includes(target)) {
    plan
      .resolveFlow(target)
      .then((t) => goRuleTarget(navigation, plan, t))
      .catch((e: unknown) => console.warn('[gen] rule flow resolve failed', e));
    return;
  }
  goRuleTarget(navigation, plan, target);
}

/**
 * An "On success, then call" rule on an answer outside 2xx: skipped. It is
 * stored as status >= 200 with no screen, and means 2xx only — the Designer's
 * ruleFor reads it that way. Without this a 400 still chained the next call.
 */
function thenCallSkipped(r: ResponseRule, status: number): boolean {
  const thenCall =
    r.source === 'status' &&
    r.op === 'gte' &&
    String(r.value) === '200' &&
    !r.navigateTo &&
    (r.callBindingId || r.callActionId);
  return Boolean(thenCall) && (status < 200 || status > 299);
}

/** A rule as the dev log names it: `body.code eq "OK"`. */
function ruleLogLabel(r: ResponseRule): string {
  return `${r.source}${r.path ? '.' + r.path : ''} ${r.op} ${JSON.stringify(r.value)}`;
}

/** Dev log of the rule that matched: the value it was tested against, and what it does. */
function logRuleMatched(r: ResponseRule, actual: unknown): void {
  console.log(
    `[RULE ✓] ${ruleLogLabel(r)} ` +
      `(actual=${JSON.stringify(actual)}) → ${r.navigateTo || r.callBindingId || r.openModalId || 'no action'}`,
  );
}

/**
 * NO rule matched — which is silent, and looks exactly like a hang.
 *
 * A save that spins and then does nothing has usually landed here: the
 * response was fine, but every rule's condition disagreed with it, so no
 * navigation fired and nothing said why. Printing the rules alongside the
 * value they were tested against turns that into a one-line diagnosis.
 */
function logNoRuleMatched(rules: ResponseRule[], status: number): void {
  console.log(
    `[RULE ✗] none of ${rules.length} matched (status=${status}) :: ` +
      rules.map((r) => ruleLogLabel(r)).join(' | '),
  );
}

/** First matching rule — rules can navigate AND/OR call another api. */
export function firstMatchingRule(
  rules: ResponseRule[],
  body: unknown,
  status: number,
): ResponseRule | null {
  for (const r of rules) {
    if (thenCallSkipped(r, status)) continue;
    const actual = ruleActual(r, body, status);
    if (matchOp(actual, r.op, r.value)) {
      if (__DEV__) logRuleMatched(r, actual);
      return r;
    }
  }
  // no rule matched: silent otherwise, and it looks exactly like a hang (see logNoRuleMatched)
  if (__DEV__ && rules.length > 0) logNoRuleMatched(rules, status);
  return null;
}

/** First matching rule's target screen name, or null. */
export function firstRuleTarget(
  rules: ResponseRule[],
  body: unknown,
  status: number,
): string | null {
  for (const r of rules) {
    if (matchOp(ruleActual(r, body, status), r.op, r.value)) return r.navigateTo;
  }
  return null;
}
